<?php
declare(strict_types=1);
use Joomla\CMS\Factory;use Joomla\CMS\Language\Text;use Joomla\CMS\Router\Route;
defined('_JEXEC') or die;
$config=$birthdays['config'];if(isset($birthdays['error'])&&!$config['show_empty'])return;
$s=htmlspecialchars((string)$params->get('moduleclass_sfx',''),ENT_QUOTES,'UTF-8');$styles=['short'=>IntlDateFormatter::SHORT,'medium'=>IntlDateFormatter::MEDIUM,'long'=>IntlDateFormatter::LONG];$formatter=new IntlDateFormatter(str_replace('-','_',Factory::getLanguage()->getTag()),$styles[$config['date_format']],IntlDateFormatter::NONE,(string)Factory::getApplication()->get('offset','UTC'));
$items=$birthdays['items']??[];$groups=[];foreach($items as$item){$key='all';$label='';if($config['group_by']==='day'){$key=$item->next_birthday->format('Y-m-d');$label=(string)$formatter->format($item->next_birthday->getTimestamp());}elseif($config['group_by']==='month'){$key=$item->next_birthday->format('Y-m');$monthFormatter=new IntlDateFormatter(str_replace('-','_',Factory::getLanguage()->getTag()),IntlDateFormatter::NONE,IntlDateFormatter::NONE,null,null,'LLLL y');$label=(string)$monthFormatter->format($item->next_birthday->getTimestamp());}elseif(in_array($config['group_by'],['club','team','project'],true)){$property=$config['group_by'].'_name';$key=(string)($item->$property?:'unknown');$label=(string)($item->$property?:Text::_('MOD_JOOMLEAGUE_BIRTHDAYS_UNKNOWN_GROUP'));}$groups[$key]??=['label'=>$label,'items'=>[]];$groups[$key]['items'][]=$item;}
$container=$config['orientation']==='horizontal'?'row row-cols-1 row-cols-md-2 row-cols-xl-3 g-3':'vstack gap-2';$surface=match($config['density']){'compact'=>'border-bottom py-2','detailed'=>'card card-body',default=>'border rounded p-3'};$imageClass=match($config['image_style']){'contain'=>'object-fit-contain','circle'=>'object-fit-cover rounded-circle',default=>'object-fit-cover'};
?>
<div class="mod-joomleague-birthdays<?php echo$s;?>" data-orientation="<?php echo$config['orientation'];?>" data-density="<?php echo$config['density'];?>">
<?php if(isset($birthdays['error'])):?><div class="alert alert-info mb-0"><?php echo Text::_($birthdays['error']);?></div><?php else:?>
<?php if($config['heading']!==''):?><h3 class="h5 jl-birthday-heading"><?php echo htmlspecialchars($config['heading'],ENT_QUOTES,'UTF-8');?></h3><?php endif;?>
<?php foreach($groups as$group):?><?php if($group['label']!==''):?><h4 class="h6 jl-birthday-group mt-3"><?php echo htmlspecialchars($group['label'],ENT_QUOTES,'UTF-8');?></h4><?php endif;?><div class="<?php echo$container;?>">
<?php foreach($group['items']as$p):$name=trim((string)$p->first_name.' '.(string)$p->last_name);?><?php if($config['orientation']==='horizontal'):?><div class="col"><?php endif;?><article class="jl-birthday-item <?php echo$surface;?> h-100 d-flex align-items-center gap-3">
<?php if($config['show_images']):?><?php if($p->picture):?><img class="jl-birthday-image <?php echo$imageClass;?> flex-shrink-0" src="<?php echo htmlspecialchars((string)$p->picture,ENT_QUOTES,'UTF-8');?>" alt="" width="<?php echo$config['image_size'];?>" height="<?php echo$config['image_size'];?>" loading="lazy"><?php else:?><span class="jl-birthday-image icon-user text-body-secondary d-inline-flex align-items-center justify-content-center flex-shrink-0" style="width:<?php echo$config['image_size'];?>px;height:<?php echo$config['image_size'];?>px" aria-hidden="true"></span><?php endif;?><?php endif;?>
<div class="flex-grow-1 min-w-0"><strong class="d-block"><?php if($config['show_person_link']):?><a class="jl-birthday-person" href="<?php echo Route::_('index.php?option=com_joomleague&amp;view=person&amp;person_id='.(int)$p->id);?>"><?php echo htmlspecialchars($name,ENT_QUOTES,'UTF-8');?></a><?php else:?><span class="jl-birthday-person"><?php echo htmlspecialchars($name,ENT_QUOTES,'UTF-8');?></span><?php endif;?></strong>
<?php if($config['show_nickname']&&$p->nickname!==''):?><span class="jl-birthday-nickname small text-body-secondary"><?php echo htmlspecialchars((string)$p->nickname,ENT_QUOTES,'UTF-8');?></span><?php endif;?><div class="small text-body-secondary">
<?php if($config['show_club']&&$p->club_name):?><span class="jl-birthday-club me-2"><?php echo htmlspecialchars((string)$p->club_name,ENT_QUOTES,'UTF-8');?></span><?php endif;?><?php if($config['show_team']&&$p->team_name):?><span class="jl-birthday-team me-2"><?php echo htmlspecialchars((string)$p->team_name,ENT_QUOTES,'UTF-8');?></span><?php endif;?><?php if($config['show_project']&&$p->project_name):?><span class="jl-birthday-project me-2"><?php echo htmlspecialchars((string)$p->project_name,ENT_QUOTES,'UTF-8');?></span><?php endif;?><?php if($config['show_person_type']&&$p->person_type):?><span class="jl-birthday-person-type badge text-bg-light border me-1"><?php echo htmlspecialchars((string)$p->person_type,ENT_QUOTES,'UTF-8');?></span><?php endif;?><?php if($config['show_role']&&$p->role_code):?><span class="jl-birthday-role badge text-bg-secondary"><?php echo htmlspecialchars((string)$p->role_code,ENT_QUOTES,'UTF-8');?></span><?php endif;?>
</div><?php if($config['show_deceased']&&$p->death_date):?><span class="jl-birthday-deceased badge text-bg-secondary"><?php echo Text::_('MOD_JOOMLEAGUE_BIRTHDAYS_DECEASED');?></span><?php endif;?></div>
<div class="text-end flex-shrink-0"><time class="jl-birthday-date d-block" datetime="<?php echo$p->next_birthday->format('Y-m-d');?>"><?php echo htmlspecialchars((string)$formatter->format($p->next_birthday->getTimestamp()),ENT_QUOTES,'UTF-8');?></time><?php if($config['show_birth_year']&&$p->birth_year!==null):?><small class="jl-birthday-year d-block text-body-secondary"><?php echo(int)$p->birth_year;?></small><?php endif;?><?php if($config['show_age']&&$p->age!==null):?><small class="jl-birthday-age d-block text-body-secondary"><?php echo Text::sprintf('MOD_JOOMLEAGUE_BIRTHDAYS_AGE',(int)$p->age);?></small><?php endif;?><?php if($config['show_days_until']):?><small class="jl-birthday-days d-block text-body-secondary"><?php echo$p->days_until===0?Text::_('MOD_JOOMLEAGUE_BIRTHDAYS_TODAY'):($p->days_until>0?Text::sprintf('MOD_JOOMLEAGUE_BIRTHDAYS_IN_DAYS',(int)$p->days_until):Text::sprintf('MOD_JOOMLEAGUE_BIRTHDAYS_DAYS_AGO',abs((int)$p->days_until)));?></small><?php endif;?></div>
</article><?php if($config['orientation']==='horizontal'):?></div><?php endif;?><?php endforeach;?></div><?php endforeach;?><?php endif;?></div>
